import sys

def solve() -> None:
    total = 0
    data = sys.stdin.read().strip().splitlines()
    for line in data:
        if not line.strip():
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        try:
            price = int(parts[0])
            percent = int(parts[1])
        except ValueError:
            # ignore malformed lines
            continue
        total += price * percent // 100
    print(f"Total Discount: {total}")

if __name__ == "__main__":
    solve()
